-- Step 1: Add sourcePosition column with default 0
ALTER TABLE priceHistory ADD COLUMN sourcePosition INT NOT NULL DEFAULT 0 AFTER jpyPrice;

-- Step 2: Drop the old unique index
ALTER TABLE priceHistory DROP INDEX uniq_price_card_source_grade_soldAt_jpyPrice;

-- Step 3: Create new unique index including sourcePosition
CREATE UNIQUE INDEX uniq_price_card_source_grade_soldAt_jpyPrice_pos 
ON priceHistory (cardId, source, grade, soldAt, jpyPrice, sourcePosition);

